#include <vector>

using namespace std;

class Solution {
public:
    int numTimesAllBlue(vector<int>& flips) {
        int res = 0, maxFlip = 0;
        for (int i = 0; i < flips.size(); ++i) {
            maxFlip = max(maxFlip, flips[i]);
            if (maxFlip == i + 1) res++;
        }
        return res;
    }
};
